import csv, collections, json

rows=list(csv.DictReader(open('input/letter_lines.csv', newline='')))

gov={
'addressee':'CL-301',
'behavioural_plan':'CL-308',
'children_named':'OI-203',
'concern':'CL-309',
'copies':'CL-305',
'delivery':'CL-306',
'enclosure':'CL-303',
'inconsistent_accounts':'OI-205',
'interim_contact':'CL-310',
'request':'CL-302',
'right_of_first_refusal':'OI-202',
'overnight_stays':'OI-204',
'salutation':'CL-304',
'sender_signature':'OI-211',
'tone':'CL-307',
'without_prejudice':'CL-311',
}

def verdict(row):
    s=row['subject']; w=row['wording'].lower(); pos=row['position'].lower()
    if s not in gov:
        return 'NOT_IN_RECORD'
    if s=='addressee':
        return 'VERIFIED' if ('mother' in w or 'catherine' in w or 'ms corwin' in w) else 'AT_ODDS'
    if s=='behavioural_plan':
        if all(k in w for k in ['confidence','stability','peer']) and ('confidence only' in w or 'confidence alone' in w):
            return 'VERIFIED'
        return 'AT_ODDS'
    if s=='children_named':
        return 'VERIFIED' if all(k in w for k in ['noor','imogen','seven','twelve']) else 'AT_ODDS'
    if s=='concern':
        return 'VERIFIED' if ('position' in w and not any(k in w for k in ['violate','contravene','appreciate','order'])) else 'AT_ODDS'
    if s=='copies':
        return 'VERIFIED' if any(k in w for k in ['no copy','do not copy','not copy','no one','nothing']) else 'AT_ODDS'
    if s=='delivery':
        return 'VERIFIED' if ('post' in w and ('counsel' in w or 'office' in w)) else 'AT_ODDS'
    if s=='enclosure':
        return 'VERIFIED' if ('certified' in w and 'enclosed' in w) else 'AT_ODDS'
    if s=='inconsistent_accounts':
        return 'VERIFIED' if all(k in w for k in ['wife','school','clinicians','sitter','me','partner','neighbours']) else 'AT_ODDS'
    if s=='interim_contact':
        return 'VERIFIED' if (all(k in w for k in ['confidence','stability','peer']) and any(k in w for k in ['all three','all addressed','together','jointly','not one in isolation'])) else 'AT_ODDS'
    if s=='request':
        return 'VERIFIED' if ('overnight' in w and ('father' in w or 'adler' in w) and ('unless' in w or 'not to' in w or 'not remain' in w or 'not stay' in w)) else 'AT_ODDS'
    if s=='right_of_first_refusal':
        return 'VERIFIED' if ('right of first refusal' in w and ('adler' in w or 'father' in w) and 'overnight' in w and ('without him' in w or 'not to be left overnight' in w)) else 'AT_ODDS'
    if s=='overnight_stays':
        return 'VERIFIED' if ('several occasions' in w and 'both children' in w and ('home or with a sitter' in w or "ms corwin's home or with a sitter" in w) and 'away' in w) else 'AT_ODDS'
    if s=='salutation':
        return 'VERIFIED' if 'dear counsel' in w else 'AT_ODDS'
    if s=='sender_signature':
        return 'VERIFIED' if ('delphine marr' in w and 'solicitor' not in w and 'for delphine' not in w) else 'AT_ODDS'
    if s=='tone':
        return 'VERIFIED' if ('firm' in w and 'formal' in w and 'brief' in w) else 'AT_ODDS'
    if s=='without_prejudice':
        return 'VERIFIED' if ('without prejudice' in w and any(k in w for k in ['soft','conciliatory','gentle','gently','without rancour','measured']) and 'firm' not in w) else 'AT_ODDS'
    return 'AT_ODDS'

counts=collections.Counter()
by_sub=collections.defaultdict(list)
for r in rows:
    v=verdict(r)
    counts[v]+=1
    by_sub[r['subject']].append((r['line_id'],v,gov.get(r['subject'],'NONE')))

print('counts:', dict(counts))
print('clarification_governed_count:', sum(1 for r in rows if gov.get(r['subject'],'').startswith('CL-')))
print()
for s in sorted(by_sub):
    print(f'### {s}')
    for line_id,v,g in by_sub[s]:
        print(f'{line_id} {v} {g}')
