        anomalies.append((r['line_id'],s,'sender_signature not own full name',w))
    elif s=='tone' and not ('firm' in w and 'formal' in w and 'brief' in w):
        anomalies.append((r['line_id'],s,'tone not firm formal brief',w))
    elif s=='without_prejudice' and not ('without prejudice' in w and any(k in w for k in ['soft','conciliatory','gentle','gently','without rancour','measured']) and 'firm' not in w):
        anomalies.append((r['line_id'],s,'without_prejudice not soft settlement tone',w))
